style.css:
@-moz-document url-prefix("http") {
/* Base Layer - Main background surface */
  body, html {
    background: #1e1f29 !important;
    color: #f6f7ee !important;
  }
  
  /* Sidebar Layer - Darker, recessed feel */
  .sidebar, nav, aside, [class*="sidebar"], [class*="nav"] {
    background: #181921 !important;
  }
  
  /* Toolbar Layer - Deepest, creates maximum depth */
  .toolbar, .header, .navbar, [class*="toolbar"], [class*="header"], [class*="navbar"] {
    background: #16171e !important;
  }
  
  /* Content Cards - Unified with sidebar */
  .content-card, .card, [class*="card"], article, section {
    background: #181921 !important;
  }
  
  /* Dividers - Subtle separation without harshness */
  .divider, hr, [class*="divider"], [class*="separator"] {
    border-color: #2d2e37 !important;
    background-color: #2d2e37 !important;
  }
  
  /* Accent Controls - Interactive elements that pop */
  a, .accent, [class*="accent"], button, input[type="button"], input[type="submit"] {
    color: #ae79f8 !important;
  }
  
  /* Hover States - Subtle elevation on interaction */
  .hovered, *:hover, button:hover, a:hover {
    background: #1e1f29 !important;
  }
  
  /* Active/Selected - Clear visual hierarchy */
  .active, .selected, [class*="active"], [class*="selected"], *:active, *:focus {
    background: #1e1f29 !important;
    color: #f6f7ee !important;
  }
  
  /* Text everywhere - Consistent readability */
  *, p, span, div, li, td, th {
    color: #f6f7ee !important;
  }
  
  /* Code blocks with accent color */
  code, pre {
    background: #181921 !important;
    color: #ae79f8 !important;
    border-radius: 4px !important;
  }
  
  /* Selection state */
  ::selection {
    background: #2d2e37 !important;
    color: #f6f7ee !important;
  }
}
